// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadInter = makeLoadFont('Inter');

// Load fonts at module level
const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: interFamily } = loadInter();



export type DocumentaryTimelineProps = Record<string, any>;

const TeamCard: React.FC<{
  team: { teamName: string; year: string; primaryColor: string; secondaryColor: string };
  width: number;
  height: number;
  idx: number;
  frame: number;
  fps: number;
}> = ({ team, width, height, idx, frame, fps }) => {
  const { teamName, year, primaryColor, secondaryColor } = team;

  // Staggered pop-in animation for each card
  const cardSpring = spring({
    frame: Math.max(0, frame - idx * 6),
    fps,
    config: { damping: 14 },
  });
  
  const scale = interpolate(cardSpring, [0, 1], [0.8, 1]);
  const opacity = interpolate(cardSpring, [0, 1], [0, 1]);

  return (
    <div
      style={{
        width: `${width}px`,
        height: `${height}px`,
        backgroundColor: primaryColor,
        position: "relative",
        overflow: "hidden",
        borderRadius: "16px",
        boxShadow: "0 20px 40px rgba(0,0,0,0.5)",
        border: "1px solid rgba(255,255,255,0.15)",
        flexShrink: 0,
        transform: `scale(${scale})`,
        opacity,
        transition: "none",
      }}
    >
      {/* Abstract Jersey Pattern - Diagonal Split */}
      <div
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          bottom: 0,
          left: "40%",
          backgroundColor: secondaryColor,
          transform: "skewX(-20deg)",
          transformOrigin: "bottom",
          transition: "none",
        }}
      />

      {/* Subtle Stripe Pattern Overlay */}
      <svg
        width="100%"
        height="100%"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          opacity: 0.15,
          transition: "none",
        }}
      >
        <defs>
          <pattern
            id={`stripe-${idx}`}
            width="40"
            height="40"
            patternUnits="userSpaceOnUse"
            patternTransform="rotate(45)"
          >
            <line x1="0" y1="0" x2="0" y2="40" stroke="#FFF" strokeWidth="4" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill={`url(#stripe-${idx})`} />
      </svg>

      {/* Vignette / Gradient for Text Readability */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "linear-gradient(to top, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0) 60%)",
          transition: "none",
        }}
      />

      {/* Card Content */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          padding: "24px",
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily: interFamily,
            fontSize: `${width * 0.08}px`,
            color: "rgba(255,255,255,0.9)",
            fontWeight: 600,
            letterSpacing: "3px",
            transition: "none",
          }}
        >
          {year}
        </div>
        <div
          style={{
            fontFamily: oswaldFamily,
            fontSize: `${width * 0.11}px`,
            color: "#FFF",
            fontWeight: 700,
            textTransform: "uppercase",
            lineHeight: 1.1,
            letterSpacing: "1px",
            textShadow: "0 4px 12px rgba(0,0,0,0.5)",
            transition: "none",
          }}
        >
          {teamName}
        </div>
      </div>
    </div>
  );
};

const DocumentaryTimeline: React.FC<DocumentaryTimelineProps> = ({
  backgroundColor = "#080808",
  transparentBackground = true,
  durationInSeconds = 10,
  playerName = "NICOLA INNOCENTIN",
  teams = [
    { teamName: "MALLOY ATHLETIC", year: "2010 - 2012", primaryColor: "#E63946", secondaryColor: "#1D3557" },
    { teamName: "UNITED FC", year: "2012 - 2014", primaryColor: "#457B9D", secondaryColor: "#F1FAEE" },
    { teamName: "CITY ROVERS", year: "2014 - 2016", primaryColor: "#2A9D8F", secondaryColor: "#264653" },
    { teamName: "SPORTING WEST", year: "2016 - 2018", primaryColor: "#D62828", secondaryColor: "#003049" },
    { teamName: "NORTHERN WANDERERS", year: "2018 - 2020", primaryColor: "#F77F00", secondaryColor: "#000000" },
    { teamName: "OLYMPIC EAGLES", year: "2020 - 2022", primaryColor: "#386641", secondaryColor: "#A7C957" },
    { teamName: "ROYAL DYNAMO", year: "2022 - 2024", primaryColor: "#3A0CA3", secondaryColor: "#4361EE" }
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive Sizing
  const referenceSize = Math.min(width, height);
  const cardWidth = referenceSize * 0.45;
  const cardHeight = cardWidth * 0.65;
  const gap = cardWidth * 0.08;
  const trackWidth = teams.length * cardWidth + (teams.length - 1) * gap;

  // Overall Timeline Animation Timing
  const introDuration = fps; // 1 second
  const exitDuration = fps; // 1 second

  // Lower Third Container Entry/Exit
  const introSpring = spring({ frame, fps, config: { damping: 14 } });
  const exitSpring = spring({
    frame: Math.max(0, frame - (totalFrames - exitDuration)),
    fps,
    config: { damping: 14 },
  });

  const containerTranslateY =
    interpolate(introSpring, [0, 1], [250, 0]) +
    interpolate(exitSpring, [0, 1], [0, 250]);
  const containerOpacity =
    interpolate(introSpring, [0, 1], [0, 1]) -
    interpolate(exitSpring, [0, 1], [0, 1]);

  // Horizontal Scroll Logic
  const maxScroll = Math.max(0, trackWidth - width * 0.9); // Keeps a 5% margin on the right when fully scrolled
  const trackTranslateX = interpolate(
    frame,
    [introDuration + 15, totalFrames - exitDuration - 15],
    [0, -maxScroll],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "flex-end",
        paddingBottom: "10%",
        transition: "none",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          transform: `translateY(${containerTranslateY}px)`,
          opacity: containerOpacity,
          display: "flex",
          flexDirection: "column",
          width: "100%",
          transition: "none",
        }}
      >
        {/* Subject Header */}
        <div style={{ paddingLeft: "5%", marginBottom: "24px", transition: "none" }}>
          <div
            style={{
              display: "inline-flex",
              alignItems: "center",
              backgroundColor: "rgba(10,10,10,0.95)",
              padding: "12px 40px",
              borderLeft: "8px solid #E63946",
              boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: oswaldFamily,
                fontSize: `${referenceSize * 0.045}px`,
                color: "#FFF",
                textTransform: "uppercase",
                letterSpacing: "4px",
                margin: 0,
                transition: "none",
              }}
            >
              {playerName}
            </div>
          </div>
        </div>

        {/* Scrolling Carousel Track Container */}
        <div
          style={{
            position: "relative",
            width: "100%",
            height: `${cardHeight}px`,
            transition: "none",
          }}
        >
          <div
            style={{
              position: "absolute",
              top: 0,
              left: "5%",
              display: "flex",
              gap: `${gap}px`,
              transform: `translateX(${trackTranslateX}px)`,
              height: "100%",
              alignItems: "center",
              transition: "none",
            }}
          >
            {teams.map((team, idx) => (
              <TeamCard
                key={idx}
                team={team}
                width={cardWidth}
                height={cardHeight}
                idx={idx}
                frame={frame}
                fps={fps}
              />
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DocumentaryTimeline;